// Public scorecard. Reads the committed evals/results.md (generated by `npm run
// evals`) directly off disk — this page shows exactly what was last committed, not a
// live re-run, so it can't silently drift from what a reviewer can reproduce locally.
import { readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import Link from "next/link";
import type { Metadata } from "next";
import { renderMarkdownLite } from "../components/markdownLite";

export const metadata: Metadata = {
  title: "Evals — grounded-rag",
  description: "Committed eval scorecard for the grounded-rag demo.",
};

export default function EvalsPage() {
  const resultsPath = join(process.cwd(), "evals", "results.md");
  const hasResults = existsSync(resultsPath);
  const content = hasResults ? readFileSync(resultsPath, "utf-8") : null;

  return (
    <div className="max-w-3xl mx-auto px-6 py-16 space-y-6">
      <header className="space-y-2">
        <Link href="/" className="text-sm text-zinc-500 dark:text-zinc-400 hover:text-zinc-900 dark:hover:text-zinc-100 underline underline-offset-2">
          ← Back
        </Link>
        <h1 className="text-xl font-semibold text-zinc-900 dark:text-zinc-100">Eval scorecard</h1>
      </header>

      {content ? (
        <div className="space-y-4">{renderMarkdownLite(content)}</div>
      ) : (
        <p className="text-zinc-600 dark:text-zinc-400">
          No results yet — run <code className="font-mono">npm run evals</code> to generate{" "}
          <code className="font-mono">evals/results.md</code>.
        </p>
      )}
    </div>
  );
}
